/**
 * UI Space — crystals: solid forms generated by point-group
 * symmetry, after the OpenGeology Mineralogy chapter "Crystal
 * Morphology and Symmetry".
 *
 * The chapter's core mechanism, implemented rather than imitated:
 * a crystal FORM is a group of faces related by symmetry. Take
 * one seed face and apply a point group's operations — rotations,
 * reflections, inversion, rotoinversion — and the seed multiplies
 * into the complete set of faces bounding the solid. A form in a
 * GENERAL position (the seed face touching no symmetry element)
 * has as many faces as the order of its point group; the general
 * form of the isometric class 4/m 3 2/m (m-3m, order 48) is the
 * HEXOCTAHEDRON, 48 faces. Crystals commonly combine several
 * forms — the beta-quartz below is a hexagonal prism combined
 * with a hexagonal dipyramid — and the same form developed to
 * different relative extents gives the same crystal a different
 * look without changing its symmetry.
 *
 * This module is pure mathematics: matrices, planes and convex
 * solids. No three.js, no React, no DOM — it is exercised
 * headless. Only CONVEX forms are supported: a solid is the
 * intersection of its forms' half-spaces.
 */

/* ---------------- 3x3 matrices (row-major) ---------------- */

const I3 = [1, 0, 0, 0, 1, 0, 0, 0, 1];

export function matMul(a, b) {
  const o = new Array(9);
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      o[r * 3 + c] = a[r * 3] * b[c] + a[r * 3 + 1] * b[3 + c] + a[r * 3 + 2] * b[6 + c];
    }
  }
  return o;
}

export function matVec(m, v) {
  return [
    m[0] * v[0] + m[1] * v[1] + m[2] * v[2],
    m[3] * v[0] + m[4] * v[1] + m[5] * v[2],
    m[6] * v[0] + m[7] * v[1] + m[8] * v[2],
  ];
}

const matKey = (m) => m.map((x) => Math.round(x * 1e6) / 1e6).join(",");

const rotZ = (deg) => {
  const a = (deg * Math.PI) / 180;
  const c = Math.cos(a), s = Math.sin(a);
  return [c, -s, 0, s, c, 0, 0, 0, 1];
};
const diag = (x, y, z) => [x, 0, 0, 0, y, 0, 0, 0, z];
/** 120° about (1,1,1): cycles the axes x → y → z → x. */
const C3_111 = [0, 0, 1, 1, 0, 0, 0, 1, 0];

/** Grow the full group from generators by closure under product. */
function groupFromGenerators(name, generators) {
  const set = new Map();
  const add = (m) => {
    const k = matKey(m);
    if (!set.has(k)) { set.set(k, m); return true; }
    return false;
  };
  add(I3);
  generators.forEach(add);
  let grew = true;
  while (grew) {
    grew = false;
    for (const m of [...set.values()]) {
      for (const g of generators) {
        if (add(matMul(m, g))) grew = true;
        if (add(matMul(g, m))) grew = true;
      }
    }
  }
  return { name, ops: [...set.values()] };
}

const GROUPS = {
  // m-3m: full octahedral symmetry (4/m 3 2/m), order 48.
  "m-3m": () => groupFromGenerators("m-3m", [rotZ(90), C3_111, diag(-1, 1, 1)]),
  // 6/mmm: hexagonal, order 24. The 6-fold is about z; the prism
  // and dipyramid seeds are read in cartesian axes with c along z.
  "6/mmm": () => groupFromGenerators("6/mmm", [rotZ(60), diag(-1, 1, 1), diag(1, 1, -1)]),
  // 4/mmm: tetragonal, order 16.
  "4/mmm": () => groupFromGenerators("4/mmm", [rotZ(90), diag(-1, 1, 1), diag(1, 1, -1)]),
  // mmm: orthorhombic, order 8.
  "mmm": () => groupFromGenerators("mmm", [diag(-1, 1, 1), diag(1, -1, 1), diag(1, 1, -1)]),
};

const _groupCache = new Map();

/** The point group's operation matrices, deduped. */
export function groupOps(name) {
  if (!_groupCache.has(name)) {
    const gen = GROUPS[name];
    if (!gen) throw new Error(`unknown point group ${name}`);
    _groupCache.set(name, gen().ops);
  }
  return _groupCache.get(name);
}

export const GROUP_ORDERS = { "m-3m": 48, "6/mmm": 24, "4/mmm": 16, "mmm": 8 };

/* ---------------- forms: seed face → its symmetry orbit ---------------- */

const vecKey = (v) => v.map((x) => Math.round(x * 1e6) / 1e6).join(",");
const normalize = (v) => {
  const l = Math.hypot(v[0], v[1], v[2]);
  return [v[0] / l, v[1] / l, v[2] / l];
};

/**
 * The planes of one form: the orbit of the seed normal under the
 * group, each plane at its own distance from the centre.
 *
 * `distances` is either a single number (every face at that
 * distance — an ordinary form) or an array giving each face its
 * own distance. The orbit's ordering is CANONICAL and stable:
 * unique normals sorted lexicographically by their rounded
 * components, so array entry i always names the same face across
 * calls — that is what lets a data value stay attached to its
 * face while the solid regrows (see FACE_DATA).
 */
export function formPlanes(groupName, seedNormal, distances = 1) {
  const ops = groupOps(groupName);
  const seed = normalize(seedNormal);
  const byKey = new Map();
  for (const op of ops) {
    const n = matVec(op, seed);
    const k = vecKey(n);
    if (!byKey.has(k)) byKey.set(k, n);
  }
  const normals = [...byKey.values()].sort((a, b) => {
    for (let i = 0; i < 3; i++) {
      const d = Math.round(a[i] * 1e6) - Math.round(b[i] * 1e6);
      if (d !== 0) return d;
    }
    return 0;
  });
  return normals.map((normal, i) => ({
    normal,
    d: Array.isArray(distances) ? (distances[i] ?? 1) : distances,
  }));
}

/** One form at a single distance: the orbit of the seed face. */
export function formFromSeed(groupName, seedNormal, distance = 1) {
  return formPlanes(groupName, seedNormal, distance);
}

/* ---------------- solids: planes → vertices, faces, edges ---------------- */

const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a, b) => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];

/** Intersect three planes; null when they are near-parallel. */
function intersect3(p, q, r) {
  const det = dot(p.normal, cross(q.normal, r.normal));
  if (Math.abs(det) < 1e-9) return null;
  const a = cross(q.normal, r.normal);
  const b = cross(r.normal, p.normal);
  const c = cross(p.normal, q.normal);
  return [
    (p.d * a[0] + q.d * b[0] + r.d * c[0]) / det,
    (p.d * a[1] + q.d * b[1] + r.d * c[1]) / det,
    (p.d * a[2] + q.d * b[2] + r.d * c[2]) / det,
  ];
}

/**
 * Combine forms (arrays of planes) into one convex solid.
 * Vertices are every triple-plane intersection satisfying all
 * half-spaces (n·v ≤ d, epsilon-tolerant), deduped. Each face is
 * its plane's on-plane vertices sorted angularly about the face
 * centroid, counter-clockwise seen from outside, so the loops
 * wind outward. Edges derive from consecutive face vertices.
 * Returns { vertices, faces (index loops), edges (index pairs) }.
 */
export function solidFromForms(forms) {
  const planes = forms.flat();
  const vKey = (v) => v.map((x) => Math.round(x * 1e4) / 1e4).join(",");
  const vertices = [];
  const seen = new Map();
  const addVert = (v) => {
    const k = vKey(v);
    if (!seen.has(k)) { seen.set(k, vertices.length); vertices.push(v); }
    return seen.get(k);
  };
  for (let i = 0; i < planes.length; i++) {
    for (let j = i + 1; j < planes.length; j++) {
      for (let k = j + 1; k < planes.length; k++) {
        const v = intersect3(planes[i], planes[j], planes[k]);
        if (!v) continue;
        let inside = true;
        for (const p of planes) {
          if (dot(p.normal, v) > p.d + 1e-5) { inside = false; break; }
        }
        if (inside) addVert(v);
      }
    }
  }
  const faces = [];
  const edgeSet = new Map();
  for (const p of planes) {
    const on = [];
    vertices.forEach((v, vi) => {
      if (Math.abs(dot(p.normal, v) - p.d) <= 1e-4) on.push(vi);
    });
    if (on.length < 3) continue;
    const c = [0, 0, 0];
    for (const vi of on) { c[0] += vertices[vi][0]; c[1] += vertices[vi][1]; c[2] += vertices[vi][2]; }
    c[0] /= on.length; c[1] /= on.length; c[2] /= on.length;
    const u = normalize(sub(vertices[on[0]], c));
    const w = cross(p.normal, u);
    const loop = on
      .map((vi) => ({
        vi,
        ang: Math.atan2(dot(sub(vertices[vi], c), w), dot(sub(vertices[vi], c), u)),
      }))
      .sort((a, b) => a.ang - b.ang)
      .map((s) => s.vi);
    faces.push(loop);
    for (let s = 0; s < loop.length; s++) {
      const a = loop[s], b = loop[(s + 1) % loop.length];
      const key = a < b ? `${a}|${b}` : `${b}|${a}`;
      if (!edgeSet.has(key)) edgeSet.set(key, [a, b]);
    }
  }
  return { vertices, faces, edges: [...edgeSet.values()] };
}

/* ---------------- the named solids ---------------- */

/**
 * Seeds, with the crystallography stated. All distances are 1
 * unless a combination needs otherwise. `zScale`, where present,
 * is a relative development applied to the finished solid's
 * vertices: an axial elongation — the same forms, developed to
 * different extents along c — not a different symmetry.
 */
export const CRYSTAL_SOLIDS = {
  cube: {
    name: "Cube", group: "m-3m",
    seeds: [{ normal: [1, 0, 0], d: 1 }],
    note: "the {100} form",
  },
  octahedron: {
    name: "Octahedron", group: "m-3m",
    seeds: [{ normal: [1, 1, 1], d: 1 }],
    note: "the {111} form",
  },
  rhombicDodecahedron: {
    name: "Rhombic dodecahedron", group: "m-3m",
    seeds: [{ normal: [1, 1, 0], d: 1 }],
    note: "the {110} form",
  },
  trapezohedron: {
    name: "Trapezohedron", group: "m-3m",
    seeds: [{ normal: [2, 1, 1], d: 1 }],
    // Care with the count: THIS trapezohedron is the isometric
    // {211} form in m-3m, and it has 24 faces. The chapter's box
    // lists trapezohedra of 6, 8 and 12 faces in other classes —
    // the face count belongs to the class, not the name.
    note: "the isometric {211} form — 24 faces in m-3m",
  },
  hexoctahedron: {
    name: "Hexoctahedron", group: "m-3m",
    seeds: [{ normal: [3, 2, 1], d: 1 }],
    // The general form of 4/m 3 2/m: the seed in a general
    // position touches no symmetry element, so the orbit is the
    // full group — 48 faces, the order of m-3m.
    note: "the general form {321} — 48 faces, the order of the group",
  },
  hexagonalPrism: {
    name: "Hexagonal prism + pinacoid", group: "6/mmm",
    seeds: [{ normal: [1, 0, 0], d: 1 }, { normal: [0, 0, 1], d: 1 }],
    note: "the prism {100} closed by the pinacoid {001}",
  },
  betaQuartz: {
    name: "Beta-quartz combination", group: "6/mmm",
    seeds: [{ normal: [1, 0, 0], d: 1 }, { normal: [1, 0, 1], d: 1 }],
    zScale: 1.8,
    // Beta-quartz is the hexagonal quartz: a hexagonal prism
    // combined with a hexagonal dipyramid. The zScale is the
    // dipyramid developed long along c relative to the prism —
    // relative development of the combined forms.
    note: "hexagonal prism {100} + hexagonal dipyramid, developed along c",
  },
  tetragonalDipyramid: {
    name: "Tetragonal dipyramid", group: "4/mmm",
    seeds: [{ normal: [1, 0, 1], d: 1 }],
    note: "the {101} form in 4/mmm",
  },
};

/** Elongate a solid along z (relative development of its forms). */
export function scaleSolidZ(solid, s) {
  if (s === 1) return solid;
  return {
    ...solid,
    vertices: solid.vertices.map(([x, y, z]) => [x, y, z * s]),
  };
}

/** Build a named solid: its forms combined, development applied. */
export function buildCrystal(id) {
  const def = CRYSTAL_SOLIDS[id];
  if (!def) throw new Error(`unknown crystal ${id}`);
  const forms = def.seeds.map((s) => formFromSeed(def.group, s.normal, s.d));
  return scaleSolidZ(solidFromForms(forms), def.zScale || 1);
}

/* ---------------- the living crystal: data on the faces ---------------- */

/**
 * The living crystal is an octahedron whose eight faces carry
 * eight values. Face i is FACE_DATA[i] — the binding holds
 * because formPlanes orders the orbit canonically, so face i is
 * the same face on every regrowth. Each face's plane distance is
 * distanceForValue(value): base 1 × (0.75 + 0.5·value01), so as a
 * value drifts its face advances or retreats and THE SHAPE IS THE
 * CHART. `value` is the seed; `wander` is the drift's pace (the
 * view walks each value toward wandering targets at ~2 Hz, in the
 * horizon monitor's tempered-walk style).
 */
export const FACE_DATA = [
  { id: "face-throughput", label: "throughput", value: 0.62, wander: 0.06 },
  { id: "face-latency", label: "latency", value: 0.35, wander: 0.09 },
  { id: "face-pressure", label: "pressure", value: 0.78, wander: 0.05 },
  { id: "face-charge", label: "charge", value: 0.50, wander: 0.07 },
  { id: "face-heat", label: "heat", value: 0.44, wander: 0.08 },
  { id: "face-flow", label: "flow", value: 0.86, wander: 0.04 },
  { id: "face-density", label: "density", value: 0.29, wander: 0.09 },
  { id: "face-signal", label: "signal", value: 0.57, wander: 0.06 },
];

/** A face's plane distance for a value in [0, 1], base distance 1. */
export function distanceForValue(value) {
  const v = Math.max(0, Math.min(1, Number(value) || 0));
  return 0.75 + 0.5 * v;
}

/** The living crystal's planes for eight current values. */
export function facePlanes(values) {
  return formPlanes("m-3m", [1, 1, 1], values.map(distanceForValue));
}

/** The living crystal's solid for eight current values. */
export function livingSolid(values) {
  return solidFromForms([facePlanes(values)]);
}
